from collections import deque
import sys

input = sys.stdin.readline

for _ in range(int(input())):
    n = int(input())
    a = list(map(int, input().split()))
    for i in range(n):
        a[i] -= i
    d = deque()
    for v in a:
        now = (1, v)
        while d:
            tail = d[-1]
            if (tail[1] + tail[0] - 1) // tail[0] <= now[1] // now[0]:
                break
            now = (now[0] + tail[0], now[1] + tail[1])
            d.pop()
        d.append(now)
    b = []
    for v in d:
        len, s = v
        for i in range(len):
            b.append((s + i) // len)
    for i in range(n - 1):
        assert b[i] <= b[i + 1]
    ans = 0
    for i in range(n):
        ans += i * (b[i] - a[i])
    print(ans)
